// Materialize a new v2 envelope after topology/path/settings changes. The old
// preservation writer remains available for byte-preserving compatibility.
// No bytes are published on failure; offsets/counts are regenerated by parsing.
bool RebuildPmmV2(const PmmSceneDocument&, PmmSceneDocument&, std::string& reason);
// Retain live free-slot payloads, shadow mode and per-model appearance when validating or
// saving a session. Opening a disk file initializes them from native defaults.
bool PreservePmmSessionState(const PmmSceneDocument&, PmmSceneDocument&);
PmmSceneDocument NewPmmScene();
bool RebuildPmmBoneInterpolation(PmmKeyTrack<PmmBoneKey>&, std::size_t channel,
                                 std::uint32_t frame);

template <class T>
bool PmmTrackChains(const PmmKeyTrack<T>& track, std::vector<std::vector<T>>& chains) {
    if (track.dense.size() > PmmKeyCapacity<T> ||
        track.sparse.size() > PmmKeyCapacity<T> - track.dense.size() ||
        track.unused.size() > PmmKeyCapacity<T> - track.dense.size())
        return false;
    std::map<std::uint32_t, const T*> sparse;
    for (const auto& entry : track.sparse)
        if (entry.index < 0 || std::size_t(entry.index) < track.dense.size() ||
            std::size_t(entry.index) >= PmmKeyCapacity<T> ||
            !sparse.emplace(std::uint32_t(entry.index), &entry.value).second)
            return false;
    for (const auto& [index, key] : track.unused)
        if (index < track.dense.size() || index >= PmmKeyCapacity<T> || key.frame ||
            sparse.count(index))
            return false;
    const auto clearedMorphSlot = [&](std::uint32_t index) {
        if constexpr (std::is_same_v<T, PmmMorphKey>) {
            if (index < track.dense.size() || index >= PmmKeyCapacity<T> || sparse.count(index))
                return false;
            const auto found = track.unused.find(index);
            // PMM serializes occupied slots only; an absent free record is zero.
            return found == track.unused.end() ||
                   (!found->second.frame && !found->second.previous && !found->second.next &&
                    !found->second.allocated && found->second.value == 0.f);
        }
        return false;
    };
    std::set<std::uint32_t> visited;
    std::map<std::uint32_t, std::uint32_t> activeRoots;
    std::vector<std::pair<std::uint32_t, std::uint32_t>> bypassed;
    std::vector<std::vector<T>> result(track.dense.size());
    for (std::size_t root = 0; root < track.dense.size(); ++root) {
        const T* key = &track.dense[root];
        // Native unlinking writes table[next].previous even when next is the
        // zero sentinel. Root 0 can therefore retain a predecessor (including
        // a subsequently freed slot); it is never followed as a chain edge.
        if (key->frame || (root && key->previous) || key->previous >= PmmKeyCapacity<T>)
            return false;
        auto index = std::uint32_t(root);
        result[root].push_back(*key);
        while (key->next) {
            const auto next = sparse.find(key->next);
            if (next == sparse.end() || !visited.insert(next->first).second ||
                next->second->frame <= key->frame || next->second->frame > 0x7fffffffU)
                return false;
            if (next->second->previous != index) {
                if constexpr (std::is_same_v<T, PmmBoneKey>)
                    bypassed.emplace_back(std::uint32_t(root), next->first);
                else if constexpr (std::is_same_v<T, PmmMorphKey>) {
                    const auto previous = next->second->previous;
                    // A freed predecessor can later be reused by registration,
                    // even for another channel. Only the first active key can
                    // retain this native shift artifact; forward edges remain
                    // ordered, unique and acyclic.
                    if (index != root || previous == next->first ||
                        previous < track.dense.size() ||
                        (!sparse.count(previous) && !clearedMorphSlot(previous)))
                        return false;
                } else
                    return false;
            }
            index = next->first;
            activeRoots.emplace(index, std::uint32_t(root));
            key = next->second;
            result[root].push_back(*key);
        }
    }
    // Native root resets and frame-line undo can retain nonzero records that
    // are detached from the root's next chain. They remain allocated/savable.
    // Validate detached ancestry without inventing a reciprocal active edge.
    // Native mouth shifting can retain detached keys pointing to an earlier
    // active key of the same channel, or to a freed slot. Neither can form a
    // cycle: active chains have already been checked and never enter this key.
    const auto detachedRoot = [&](std::uint32_t index) {
        for (std::size_t n = 0; n <= sparse.size(); ++n) {
            if (index < track.dense.size())
                return index;
            if (const auto found = activeRoots.find(index); found != activeRoots.end())
                return found->second;
            const auto found = sparse.find(index);
            if (found == sparse.end())
                break;
            index = found->second->previous;
        }
        return std::uint32_t(-1);
    };
    for (const auto& [index, key] : sparse) {
        if (visited.count(index))
            continue;
        if (!key->frame || key->frame > 0x7fffffffU)
            return false;
        const T* previous = nullptr;
        if (key->previous < track.dense.size())
            previous = &track.dense[key->previous];
        else if (const auto found = sparse.find(key->previous); found != sparse.end())
            previous = found->second;
        if (!previous || previous->frame >= key->frame)
            return false;
        if (key->next) {
            const auto found = sparse.find(key->next);
            const auto active = activeRoots.find(key->next);
            const bool shiftedMorph = std::is_same_v<T, PmmMorphKey> &&
                                      active != activeRoots.end() &&
                                      detachedRoot(key->previous) == active->second;
            if (found == sparse.end() ? !clearedMorphSlot(key->next)
                                      : !shiftedMorph && found->second->frame <= key->frame)
                return false;
        }
    }
    // Depending on allocation order, native bone undo can restore the next
    // key's predecessor before the frame-zero merge. Permit only a detached
    // predecessor from this same channel that still points to that next key.
    for (const auto& [root, index] : bypassed) {
        const auto& key = *sparse.at(index);
        const auto previous = sparse.find(key.previous);
        if (previous == sparse.end() || visited.count(key.previous) ||
            previous->second->next != index || previous->second->frame >= key.frame)
            return false;
        auto ancestor = key.previous;
        while (ancestor >= track.dense.size())
            ancestor = sparse.at(ancestor)->previous;
        if (ancestor != root)
            return false;
    }
    chains = std::move(result);
    return true;
}

// Includes detached records, whose channel follows predecessor ancestry.
// The active forward chain remains the source for playback and registration.
template <class T>
bool PmmRecordChannels(const PmmKeyTrack<T>& track,
                       std::map<std::uint32_t, std::uint32_t>& channels) {
    std::vector<std::vector<T>> checked;
    if (!PmmTrackChains(track, checked))
        return false;
    std::map<std::uint32_t, const T*> records;
    std::map<std::uint32_t, std::uint32_t> result;
    for (std::uint32_t i = 0; i < track.dense.size(); ++i)
        result.emplace(i, i);
    for (const auto& key : track.sparse)
        records.emplace(std::uint32_t(key.index), &key.value);
    // A native mouth shift can free the first key without repairing the next
    // key's predecessor. Active ownership comes from the validated forward chain.
    for (std::uint32_t root = 0; root < track.dense.size(); ++root)
        for (auto next = track.dense[root].next; next; next = records.at(next)->next)
            result.emplace(next, root);
    for (const auto& [index, key] : records) {
        auto previous = index;
        std::vector<std::uint32_t> path;
        while (!result.count(previous)) {
            path.push_back(previous);
            previous = records.at(previous)->previous;
        }
        for (auto i : path)
            result.emplace(i, result.at(previous));
    }
    channels = std::move(result);
    return true;
}

// Restore only captured native slots; absent sparse slots are represented by
// frame zero. Capture the displaced slots for redo, including their holes.
template <class T>
bool RestorePmmKeyRecords(PmmKeyTrack<T>& track, const std::map<std::uint32_t, T>& saved,
                          std::map<std::uint32_t, T>& displaced) {
    auto next = track;
    std::map<std::uint32_t, T> old;
    for (const auto& [index, key] : saved) {
        if (index >= PmmKeyCapacity<T>)
            return false;
        if (index < next.dense.size()) {
            old.emplace(index, next.dense[index]);
            next.dense[index] = key;
        } else {
            auto found = std::find_if(next.sparse.begin(), next.sparse.end(),
                                      [&](const auto& record) { return record.index == index; });
            old.emplace(index, found != next.sparse.end() ? found->value
                               : next.unused.count(index) ? next.unused.at(index)
                                                          : T{});
            if (found != next.sparse.end()) {
                if (key.frame)
                    found->value = key;
                else
                    next.sparse.erase(found);
            } else if (key.frame) {
                next.sparse.push_back({std::int32_t(index), 0, key});
            }
            if (key.frame)
                next.unused.erase(index);
            else
                next.unused[index] = key;
        }
    }
    std::vector<std::vector<T>> checked;
    if (!PmmTrackChains(next, checked))
        return false;
    std::sort(next.sparse.begin(), next.sparse.end(),
              [](const auto& a, const auto& b) { return a.index < b.index; });
    track = std::move(next);
    displaced = std::move(old);
    return true;
}
template <class T>
bool BuildPmmTrack(const std::vector<std::vector<T>>& chains, PmmKeyTrack<T>& output) {
    if (chains.size() > PmmKeyCapacity<T>)
        return false;
    PmmKeyTrack<T> next;
    next.dense.resize(chains.size());
    next.denseRecordOffsets.resize(chains.size());
    for (std::size_t root = 0; root < chains.size(); ++root) {
        const auto& keys = chains[root];
        if (keys.empty() || keys.front().frame)
            return false;
        auto index = std::uint32_t(root);
        for (std::size_t k = 0; k < keys.size(); ++k) {
            auto value = keys[k];
            if (value.frame > 0x7fffffffU || (k && keys[k - 1].frame >= value.frame))
                return false;
            value.previous = k ? index : 0;
            const auto current = k ? std::uint32_t(next.dense.size() + next.sparse.size()) : index;
            value.next = k + 1 == keys.size()
                             ? 0
                             : std::uint32_t(next.dense.size() + next.sparse.size() + (k ? 1 : 0));
            if (!k)
                next.dense[root] = value;
            else {
                if (next.dense.size() + next.sparse.size() >= PmmKeyCapacity<T>)
                    return false;
                next.sparse.push_back({std::int32_t(current), 0, value});
            }
            index = current;
        }
    }
    output = std::move(next);
    return true;
}

// Insert one frame before all non-root keys at/after the cursor. Stable record
// indices, links, selection bytes and payloads are retained. Validate the whole
// operation first so an overflow never leaves a partially shifted track.
template <class T>
bool InsertPmmFrameLine(PmmKeyTrack<T>& track, std::uint32_t frame, unsigned& affected) {
    std::vector<std::vector<T>> chains;
    if (frame > 0x7fffffffU || !PmmTrackChains(track, chains))
        return false;
    unsigned count = 0;
    for (const auto& record : track.sparse)
        if (record.value.frame >= frame) {
            if (record.value.frame == 0x7fffffffU)
                return false;
            ++count;
        }
    for (auto& record : track.sparse)
        if (record.value.frame >= frame)
            ++record.value.frame;
    affected = count;
    return true;
}
template <class T>
bool RegisterPmmKey(PmmKeyTrack<T>& track, std::size_t channel, T key,
                    std::map<std::uint32_t, T>* captured = nullptr) {
    std::vector<std::vector<T>> chains;
    if (key.frame > 0x7fffffffU || !PmmTrackChains(track, chains) || channel >= chains.size())
        return false;
    std::map<std::uint32_t, T*> records;
    for (std::size_t i = 0; i < track.dense.size(); ++i)
        records.emplace(std::uint32_t(i), &track.dense[i]);
    for (auto& record : track.sparse)
        records.emplace(std::uint32_t(record.index), &record.value);
    auto index = std::uint32_t(channel);
    while (records.at(index)->frame < key.frame && records.at(index)->next)
        index = records.at(index)->next;
    auto& current = *records.at(index);
    const auto capture = [&](std::uint32_t i) {
        if (captured)
            captured->emplace(i, records.count(i)        ? *records.at(i)
                                 : track.unused.count(i) ? track.unused.at(i)
                                                         : T{});
    };
    if (current.frame == key.frame) {
        // A payload overwrite must not relocate any key, including this one.
        key.previous = current.previous;
        key.next = current.next;
        capture(index);
        current = std::move(key);
        return true;
    }
    if (track.dense.size() + track.sparse.size() >= PmmKeyCapacity<T>)
        return false;
    // Button registration reuses the first free record after the roots.
    auto free = std::uint32_t(track.dense.size());
    while (records.count(free))
        ++free;
    if (current.frame < key.frame) {
        capture(index);
        capture(free);
        key.previous = index;
        key.next = 0;
        current.next = free;
    } else {
        capture(current.previous);
        capture(index);
        capture(free);
        key.previous = current.previous;
        key.next = index;
        records.at(current.previous)->next = free;
        current.previous = free;
    }
    track.sparse.push_back({std::int32_t(free), 0, std::move(key)});
    track.unused.erase(free);
    std::sort(track.sparse.begin(), track.sparse.end(),
              [](const auto& a, const auto& b) { return a.index < b.index; });
    return true;
}
template <class T>
bool DeletePmmKey(PmmKeyTrack<T>& track, std::size_t channel, std::uint32_t frame) {
    // MMD retains the frame-zero root; deleting it cannot destroy the channel.
    if (!frame)
        return false;
    std::vector<std::vector<T>> chains;
    if (!PmmTrackChains(track, chains) || channel >= chains.size())
        return false;
    const auto& keys = chains[channel];
    const auto found =
        std::find_if(keys.begin(), keys.end(), [frame](const T& k) { return k.frame == frame; });
    if (found == keys.end())
        return false;
    std::map<std::uint32_t, T*> records;
    for (std::size_t i = 0; i < track.dense.size(); ++i)
        records.emplace(std::uint32_t(i), &track.dense[i]);
    for (auto& record : track.sparse)
        records.emplace(std::uint32_t(record.index), &record.value);
    auto& previous = *records.at(found->previous);
    const auto removed = previous.next;
    previous.next = found->next;
    records.at(found->next)->previous = found->previous;
    if constexpr (std::is_same_v<T, PmmBoneKey>) {
        auto retired = *found;
        retired.frame = retired.previous = retired.next = 0;
        retired.position = {};
        retired.rotation = {0, 0, 0, 1};
        retired.allocated = 0;
        track.unused[removed] = retired;
    }
    track.sparse.erase(std::find_if(track.sparse.begin(), track.sparse.end(),
                                    [&](const auto& record) { return record.index == removed; }));
    return true;
}
